const langCodes = {id:'ID',en:'EN',no:'NO',de:'DE',ja:'JA',zh:'ZH'};
let currentLang = localStorage.getItem('maba-lang') || 'id';

function setLanguage(lang) {
  if (!translations[lang]) return;
  currentLang = lang;
  localStorage.setItem('maba-lang', lang);
  document.documentElement.lang = lang;
  document.getElementById('currentLang').textContent = langCodes[lang];
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    if (translations[lang][key]) el.textContent = translations[lang][key];
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.dataset.i18nPlaceholder;
    if (translations[lang][key]) el.placeholder = translations[lang][key];
  });
  resetChat();
}

const langBtn = document.getElementById('langBtn');
const langMenu = document.getElementById('langMenu');
langBtn.addEventListener('click', () => {
  const open = !langMenu.hidden;
  langMenu.hidden = open;
  langBtn.setAttribute('aria-expanded', String(!open));
});
langMenu.querySelectorAll('button').forEach(btn => btn.addEventListener('click', () => {
  setLanguage(btn.dataset.lang);
  langMenu.hidden = true;
  langBtn.setAttribute('aria-expanded','false');
}));
document.addEventListener('click', (e) => {
  if (!e.target.closest('.language-picker')) { langMenu.hidden = true; langBtn.setAttribute('aria-expanded','false'); }
});

const themeToggle = document.getElementById('themeToggle');
const savedTheme = localStorage.getItem('maba-theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
document.documentElement.dataset.theme = savedTheme;
themeToggle.addEventListener('click', () => {
  const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
  document.documentElement.dataset.theme = next;
  localStorage.setItem('maba-theme', next);
});

