const chatMessages = document.getElementById('chatMessages');
const chatForm = document.getElementById('chatForm');
const chatInput = document.getElementById('chatInput');

function addMessage(text, type='bot') {
  const div = document.createElement('div');
  div.className = `demo-message ${type}`;
  div.textContent = text;
  chatMessages.appendChild(div);
  chatMessages.scrollTop = chatMessages.scrollHeight;
}
function resetChat(){ chatMessages.innerHTML=''; addMessage(copy[currentLang].welcome); }
function getAnswer(text) {
  const q = text.toLowerCase();
  if (/harga|price|pris|preis|料金|价格/.test(q)) return copy[currentLang].price;
  if (/jam|operasional|hour|open|åpning|öffnungs|営業時間|营业/.test(q)) return copy[currentLang].hours;
  if (/custom|kustom|sesuai|tilpass|anpass|カスタ|定制/.test(q)) return copy[currentLang].custom;
  if (/knowledge|dokumen|faq|data|kunnskap|wissen|ナレッジ|知识/.test(q)) return copy[currentLang].knowledge;
  if (/whatsapp|telegram|channel|kanal|チャネル|渠道/.test(q)) return copy[currentLang].channel;
  return copy[currentLang].fallback;
}
const demoSessionId = `demo:${Math.random().toString(36).slice(2)}`;
async function askMabaAI(text) {
  const response = await fetch('/api/chat', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({ message:text, sessionId:demoSessionId, channel:'website', workspaceId:authState?.user?.workspace?.id || 'default' }) });
  const data = await response.json();
  if (!response.ok || !data.ok) throw new Error(data.error || 'AI request failed');
  return data.text;
}
async function submitDemoMessage(text) {
  if (!text) return;
  addMessage(text,'user');
  const typing = document.createElement('div'); typing.className='demo-message bot'; typing.textContent='•••'; chatMessages.appendChild(typing); chatMessages.scrollTop=chatMessages.scrollHeight;
  try { const answer = await askMabaAI(text); typing.remove(); addMessage(answer,'bot'); }
  catch (err) { typing.remove(); addMessage(`${getAnswer(text)}

[Phase 4 setup: ${err.message}]`,'bot'); }
}
chatForm.addEventListener('submit', async e => {
  e.preventDefault();
  const text = chatInput.value.trim(); if (!text) return;
  chatInput.value='';
  await submitDemoMessage(text);
});

