const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

const observer = new IntersectionObserver(entries => entries.forEach(entry => {
  if (!entry.isIntersecting) return;
  entry.target.classList.add('visible');
  observer.unobserve(entry.target);
}), {threshold:.1, rootMargin:'0px 0px -35px'});
document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

// Phase 2: scroll progress + premium sticky header + active section state
const progressBar = document.getElementById('scrollProgress');
const siteHeader = document.getElementById('siteHeader');
const navLinks = [...document.querySelectorAll('.desktop-nav a')];
const navSections = navLinks.map(link => document.querySelector(link.getAttribute('href'))).filter(Boolean);

function handleScrollUI() {
  const maxScroll = document.documentElement.scrollHeight - innerHeight;
  const ratio = maxScroll > 0 ? scrollY / maxScroll : 0;
  progressBar.style.width = `${Math.min(100, Math.max(0, ratio * 100))}%`;
  siteHeader.classList.toggle('scrolled', scrollY > 24);

  let currentId = '';
  navSections.forEach(section => {
    if (scrollY >= section.offsetTop - 180) currentId = section.id;
  });
  navLinks.forEach(link => link.classList.toggle('active', link.getAttribute('href') === `#${currentId}`));
}
addEventListener('scroll', handleScrollUI, {passive:true});
addEventListener('resize', handleScrollUI);
handleScrollUI();

// Animated counters run only once when the metric row enters view.
const metricRow = document.querySelector('.hero-metrics');
if (metricRow) {
  const metricObserver = new IntersectionObserver(entries => {
    if (!entries[0].isIntersecting) return;
    document.querySelectorAll('[data-counter]').forEach(el => {
      const target = Number(el.dataset.counter || 0);
      if (reduceMotion) { el.textContent = target; return; }
      const start = performance.now();
      const duration = 900;
      const tick = now => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        el.textContent = Math.round(target * eased);
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    });
    metricObserver.disconnect();
  }, {threshold:.35});
  metricObserver.observe(metricRow);
}

// Soft cursor glow for desktop pointer devices.
const cursorGlow = document.getElementById('cursorGlow');
if (!reduceMotion && matchMedia('(pointer:fine)').matches && cursorGlow) {
  addEventListener('pointermove', e => {
    cursorGlow.style.left = `${e.clientX}px`;
    cursorGlow.style.top = `${e.clientY}px`;
  }, {passive:true});
}

// Lightweight 3D tilt: intentionally subtle to keep the UI premium.
if (!reduceMotion && matchMedia('(pointer:fine)').matches) {
  document.querySelectorAll('.tilt-card').forEach(card => {
    const max = Number(card.dataset.tilt || 3);
    card.addEventListener('pointermove', e => {
      const r = card.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - .5;
      const y = (e.clientY - r.top) / r.height - .5;
      card.style.setProperty('--ry', `${x * max}deg`);
      card.style.setProperty('--rx', `${-y * max}deg`);
    });
    card.addEventListener('pointerleave', () => {
      card.style.setProperty('--ry', '0deg');
      card.style.setProperty('--rx', '0deg');
    });
  });

  document.querySelectorAll('.magnetic').forEach(button => {
    button.addEventListener('pointermove', e => {
      const r = button.getBoundingClientRect();
      const x = (e.clientX - r.left - r.width / 2) * .08;
      const y = (e.clientY - r.top - r.height / 2) * .08;
      button.style.translate = `${x}px ${y}px`;
    });
    button.addEventListener('pointerleave', () => { button.style.translate = ''; });
  });
}

// Gentle parallax inside the hero product mockup.
const parallaxChat = document.getElementById('parallaxChat');
const productVisual = document.querySelector('.product-visual');
if (!reduceMotion && parallaxChat && productVisual && matchMedia('(pointer:fine)').matches) {
  productVisual.addEventListener('pointermove', e => {
    const r = productVisual.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - .5;
    const y = (e.clientY - r.top) / r.height - .5;
    parallaxChat.style.transform = `translate(calc(-50% + ${x * 11}px), calc(-47% + ${y * 11}px)) rotate(${-2 + x * 1.4}deg)`;
  });
  productVisual.addEventListener('pointerleave', () => {
    parallaxChat.style.transform = 'translate(-50%,-47%) rotate(-2deg)';
  });
}

