// ---- Phase 4 Human Inbox ----
function shortTime(value) {
  if (!value) return '';
  const d = new Date(value); if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat(currentLang === 'id' ? 'id-ID' : undefined,{hour:'2-digit',minute:'2-digit'}).format(d);
}
function channelLabel(channel='website') { return String(channel).replace('website-demo','website').replace('website-widget','website').toUpperCase(); }
function findHandoffForConversation(id) { return (inboxData.handoffs || []).find(h => h.conversationId === id); }
function renderInbox() {
  if (!conversationList || !conversationPane) return;
  const conversations = [...(inboxData.conversations || [])].sort((a,b) => {
    const rank = s => s === 'waiting' ? 0 : s === 'human' ? 1 : 2;
    return rank(a.status)-rank(b.status) || new Date(b.updatedAt)-new Date(a.updatedAt);
  });
  const waiting = conversations.filter(c=>c.status==='waiting').length;
  const active = conversations.filter(c=>c.status==='human').length;
  document.getElementById('inboxWaitingCount').textContent = waiting;
  document.getElementById('inboxActiveCount').textContent = active;
  if (!conversations.length) {
    conversationList.innerHTML = '<div class="empty-state">Belum ada conversation. Coba chat demo dan minta “human” untuk mengetes handoff.</div>';
    conversationPane.innerHTML = '<div class="conversation-empty"><span>↗</span><strong>Human Inbox siap</strong><small>Percakapan yang meminta manusia akan muncul di sini lengkap dengan context dan history.</small></div>';
    return;
  }
  conversationList.innerHTML = conversations.map(c => `
    <button class="conversation-card ${c.id===activeConversationId?'active':''}" type="button" data-conversation-id="${c.id}">
      <span class="conversation-avatar">${escapeHtml((c.customerName||'C').slice(0,1).toUpperCase())}</span>
      <span class="conversation-card-main"><strong>${escapeHtml(c.customerName||'Customer')}</strong><p>${escapeHtml(c.lastMessage||'No messages yet')}</p></span>
      <span class="conversation-card-meta"><small>${shortTime(c.updatedAt)}</small><span class="conversation-status ${escapeHtml(c.status)}">${escapeHtml(c.status)}</span></span>
    </button>`).join('');
  conversationList.querySelectorAll('[data-conversation-id]').forEach(btn => btn.addEventListener('click', () => openConversation(btn.dataset.conversationId)));
  if (activeConversationId) {
    const activeConversation=conversations.find(c=>c.id===activeConversationId); if(activeConversation) renderConversationPane(activeConversation);
  }
}
function renderConversationPane(c) {
  if (!conversationPane || !c) return;
  activeConversationId=c.id;
  const handoff=findHandoffForConversation(c.id);
  const canReply=c.status==='human';
  const messages=(c.messages||[]).map(m=>`<div class="conversation-message ${escapeHtml(m.role)}"><div>${escapeHtml(m.content)}</div><small>${escapeHtml(m.role==='human'?(m.meta?.agent||'Human agent'):m.role)} • ${shortTime(m.createdAt)}</small></div>`).join('') || '<div class="empty-state">No messages.</div>';
  conversationPane.innerHTML=`
    <div class="conversation-head">
      <div class="conversation-head-main"><span class="conversation-avatar">${escapeHtml((c.customerName||'C').slice(0,1).toUpperCase())}</span><div><strong>${escapeHtml(c.customerName||'Customer')}</strong><small>${channelLabel(c.channel)} • ${escapeHtml(c.status)}${c.assignedTo?` • ${escapeHtml(c.assignedTo)}`:''}</small></div></div>
      <div class="conversation-actions">
        ${c.status==='waiting'&&handoff?'<button class="studio-primary" id="assignConversation" type="button">Take over</button>':''}
        ${['waiting','human'].includes(c.status)?'<button class="studio-secondary" id="returnConversationAI" type="button">Return to AI</button>':''}
      </div>
    </div>
    <div class="conversation-messages" id="conversationMessages">${messages}</div>
    <form class="human-reply-form" id="humanReplyForm" ${canReply?'':'hidden'}><textarea id="humanReplyText" placeholder="Reply as human agent…"></textarea><button class="studio-primary" type="submit">Send</button></form>`;
  const scroll=document.getElementById('conversationMessages'); if(scroll)scroll.scrollTop=scroll.scrollHeight;
  document.getElementById('assignConversation')?.addEventListener('click',async()=>{
    try{setFormMessage(inboxMessage,'Taking over conversation…');await apiRequest(`/api/handoffs/${handoff.id}/assign`,{method:'POST'});setFormMessage(inboxMessage,'Human agent connected.','success');await loadStudio();}
    catch(err){setFormMessage(inboxMessage,err.message,'error');}
  });
  document.getElementById('returnConversationAI')?.addEventListener('click',async()=>{
    try{await apiRequest(`/api/conversations/${c.id}/return-ai`,{method:'POST'});setFormMessage(inboxMessage,'Conversation returned to AI.','success');await loadStudio();}
    catch(err){setFormMessage(inboxMessage,err.message,'error');}
  });
  document.getElementById('humanReplyForm')?.addEventListener('submit',async e=>{
    e.preventDefault();const input=document.getElementById('humanReplyText');const text=input.value.trim();if(!text)return;
    try{input.disabled=true;await apiRequest(`/api/conversations/${c.id}/reply`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text})});input.value='';setFormMessage(inboxMessage,'Reply sent.','success');await loadStudio();}
    catch(err){setFormMessage(inboxMessage,err.message,'error');}finally{input.disabled=false;}
  });
  conversationList?.querySelectorAll('.conversation-card').forEach(card=>card.classList.toggle('active',card.dataset.conversationId===c.id));
}
function openConversation(id) {
  activeConversationId=id;
  const c=(inboxData.conversations||[]).find(x=>x.id===id);
  if(c) renderConversationPane(c);
}

