function renderKnowledge() {
  if (!knowledgeList) return;
  const docs = studioKnowledge.documents || [];
  knowledgeTotals.textContent = `${studioKnowledge.totals?.documents || 0} documents • ${studioKnowledge.totals?.chunks || 0} chunks`;
  if (!docs.length) {
    knowledgeList.innerHTML = `<div class="empty-state">${translations[currentLang].emptyKnowledge || 'No knowledge yet.'}</div>`;
    return;
  }
  knowledgeList.innerHTML = docs.map(doc => `
    <div class="knowledge-item" data-doc-id="${doc.id}">
      <div class="file-badge">${String(doc.type || 'FILE').slice(0,4)}</div>
      <div><strong>${escapeHtml(doc.name)}</strong><small>${doc.chunks} chunks • ${Math.round((doc.chars || 0)/100)/10}k chars • <span class="${doc.indexed ? 'indexed' : 'pending-index'}">${doc.indexed ? 'indexed' : 'pending index'}</span></small></div>
      <button type="button" data-delete-doc="${doc.id}" title="Delete">×</button>
    </div>`).join('');
  document.querySelectorAll('[data-delete-doc]').forEach(btn => btn.addEventListener('click', async () => {
    try {
      const data = await apiRequest(`/api/knowledge/${btn.dataset.deleteDoc}`, { method:'DELETE' });
      studioKnowledge = { documents:data.documents, totals:data.totals };
      renderKnowledge(); updateStudioSummary();
    } catch (err) { setFormMessage(knowledgeMessage, err.message, 'error'); }
  }));
}
function escapeHtml(text='') { return String(text).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }

function updateChannelCards() {
  if (!studioConfig?.channels) return;
  ['telegram','whatsapp','instagram','website'].forEach(type => {
    const card = document.querySelector(`[data-channel-card="${type}"]`);
    if (!card) return;
    const pill = card.querySelector('.connection-pill');
    const cfg = studioConfig.channels[type];
    const connected = Boolean(cfg?.connected);
    pill.classList.toggle('connected', connected);
    pill.textContent = connected ? (type === 'telegram' && cfg.botUsername ? `@${cfg.botUsername}` : 'Connected') : 'Not connected';
  });
}
function updateStudioSummary() {
  const aiReady = Boolean(studioConfig?.ai?.configured);
  aiStatusDot?.classList.toggle('ready', aiReady);
  if (aiStatusText) aiStatusText.textContent = aiReady ? studioConfig.ai.model : 'Not configured';
  if (knowledgeStatusText) knowledgeStatusText.textContent = `${studioKnowledge.totals?.documents || 0} files • ${studioKnowledge.totals?.chunks || 0} chunks`;
  if (channelStatusText) {
    const count = studioConfig?.channels ? Object.values(studioConfig.channels).filter(c => c.connected).length : 0;
    channelStatusText.textContent = `${count} connected`;
  }
  if (handoffStatusText) handoffStatusText.textContent = `${studioStats?.humanWaiting || 0} waiting`;
  if (creditStatusText) creditStatusText.textContent = studioStats?.usage ? `${studioStats.usage.creditsRemaining} left` : '—';
  document.getElementById('usageCredits') && (document.getElementById('usageCredits').textContent = studioStats?.usage?.creditsRemaining ?? '—');
  document.getElementById('usageReplies') && (document.getElementById('usageReplies').textContent = studioStats?.usage?.aiReplies ?? 0);
  document.getElementById('usageConversations') && (document.getElementById('usageConversations').textContent = studioStats?.conversations ?? 0);
  updateChannelCards();
}
function populateStudioConfig() {
  if (!studioConfig) return;
  const ai = studioConfig.ai;
  document.getElementById('chatModel').value = ai.model || 'gpt-5.6';
  document.getElementById('embeddingModel').value = ai.embeddingModel || 'text-embedding-3-small';
  document.getElementById('assistantName').value = ai.assistantName || 'Nexora Assistant';
  document.getElementById('systemPrompt').value = ai.systemPrompt || '';
  const hint = document.getElementById('apiKeyHint');
  hint.textContent = ai.configured ? `Saved securely: ${ai.apiKeyMasked}` : (translations[currentLang].keyNotSaved || 'No saved key yet.');
  const web = studioConfig.channels.website || {};
  document.getElementById('widgetTitle').value = web.title || 'Nexora Assistant';
  document.getElementById('widgetWelcome').value = web.welcomeMessage || 'Halo 👋 Ada yang bisa saya bantu?';
  document.getElementById('widgetAccent').value = web.accent || '#d9ff43';
  document.getElementById('widgetAccentText').value = web.accent || '#d9ff43';
  const workspaceId = authState?.user?.workspace?.id || studioConfig.workspaceId || 'default';
  document.getElementById('embedCode').textContent = `<script src="${location.origin}/widget.js" data-maba-business data-workspace="${workspaceId}"></script>`;
  const handoff = studioConfig.handoff || {};
  const enabled = document.getElementById('handoffEnabled'); if (enabled) enabled.checked = handoff.enabled !== false;
  const triggers = document.getElementById('handoffTriggerWords'); if (triggers) triggers.value = (handoff.triggerWords || []).join(', ');
  const waiting = document.getElementById('handoffWaitingMessage'); if (waiting) waiting.value = handoff.waitingMessage || '';
  const active = document.getElementById('handoffActiveMessage'); if (active) active.value = handoff.activeMessage || '';
}
async function loadStudio() {
  if (!authState?.user) return updateAuthUI();
  try {
    const [configData, knowledgeData, statsData, inbox] = await Promise.all([
      apiRequest('/api/config'), apiRequest('/api/knowledge'), apiRequest('/api/dashboard/stats'), apiRequest('/api/inbox')
    ]);
    studioConfig = configData.config;
    studioKnowledge = { documents:knowledgeData.documents, totals:knowledgeData.totals };
    studioStats = statsData.stats;
    inboxData = { handoffs:inbox.handoffs || [], conversations:inbox.conversations || [] };
    populateStudioConfig(); renderKnowledge(); updateStudioSummary(); renderInbox(); updateAuthUI();
  } catch (err) {
    if (/Login diperlukan/i.test(err.message)) { authState.user = null; updateAuthUI(); return; }
    if (aiStatusText) aiStatusText.textContent = 'Backend offline';
    setFormMessage(aiFormMessage, err.message, 'error');
  }
}
document.getElementById('refreshStudio')?.addEventListener('click', loadStudio);

