document.getElementById('manualKnowledgeForm')?.addEventListener('submit', async e => {
  e.preventDefault();
  const title = document.getElementById('manualKnowledgeTitle').value;
  const text = document.getElementById('manualKnowledgeText').value;
  setFormMessage(knowledgeMessage, 'Adding knowledge…');
  try {
    const data = await apiRequest('/api/knowledge/text', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({title,text}) });
    studioKnowledge = { documents:data.documents, totals:data.totals };
    document.getElementById('manualKnowledgeTitle').value=''; document.getElementById('manualKnowledgeText').value='';
    renderKnowledge(); updateStudioSummary(); setFormMessage(knowledgeMessage, 'Manual knowledge ditambahkan.', 'success');
  } catch (err) { setFormMessage(knowledgeMessage, err.message, 'error'); }
});
document.getElementById('reindexKnowledge')?.addEventListener('click', async () => {
  setFormMessage(knowledgeMessage, 'Re-indexing knowledge with embeddings…');
  try {
    const data = await apiRequest('/api/knowledge/reindex', { method:'POST' });
    studioKnowledge = { documents:data.documents, totals:data.totals }; renderKnowledge(); updateStudioSummary();
    setFormMessage(knowledgeMessage, `Re-index complete • ${data.updated} chunk updated.`, 'success');
  } catch (err) { setFormMessage(knowledgeMessage, err.message, 'error'); }
});

// Website Widget
const widgetAccent = document.getElementById('widgetAccent');
const widgetAccentText = document.getElementById('widgetAccentText');
widgetAccent?.addEventListener('input', () => widgetAccentText.value = widgetAccent.value);
widgetAccentText?.addEventListener('input', () => { if (/^#[0-9a-f]{6}$/i.test(widgetAccentText.value)) widgetAccent.value = widgetAccentText.value; });
document.getElementById('widgetConfigForm')?.addEventListener('submit', async e => {
  e.preventDefault();
  setFormMessage(widgetMessage, 'Saving widget…');
  try {
    await apiRequest('/api/channels/website/save', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({ title:document.getElementById('widgetTitle').value, welcomeMessage:document.getElementById('widgetWelcome').value, accent:widgetAccentText.value }) });
    setFormMessage(widgetMessage, 'Website widget saved.', 'success'); await loadStudio();
  } catch (err) { setFormMessage(widgetMessage, err.message, 'error'); }
});
document.getElementById('copyEmbed')?.addEventListener('click', async () => {
  try { await navigator.clipboard.writeText(document.getElementById('embedCode').textContent); setFormMessage(widgetMessage, 'Embed code copied.', 'success'); }
  catch { setFormMessage(widgetMessage, 'Copy gagal. Pilih code secara manual.', 'error'); }
});

// Channel Connection Dialog
const channelDialog = document.getElementById('channelDialog');
const channelDialogTitle = document.getElementById('channelDialogTitle');
const channelFields = document.getElementById('channelFields');
const channelDialogNote = document.getElementById('channelDialogNote');
const channelMessage = document.getElementById('channelMessage');
const connectChannelButton = document.getElementById('connectChannel');
const disconnectChannelButton = document.getElementById('disconnectChannel');
let activeChannel = null;

const channelSchemas = {
  telegram: {
    title:'Connect Telegram',
    fields: cfg => `
      <label>Telegram Bot Token<input name="botToken" type="password" placeholder="123456:ABC..." ${cfg.botTokenMasked ? '' : 'required'}><small>${cfg.botTokenMasked ? `Saved: ${cfg.botTokenMasked}` : 'Get it from @BotFather'}</small></label>
      <div class="row"><label>Mode<select name="mode"><option value="polling" ${cfg.mode!=='webhook'?'selected':''}>Polling — recommended for local</option><option value="webhook" ${cfg.mode==='webhook'?'selected':''}>Webhook — production</option></select></label><label>Public Base URL<input name="publicBaseUrl" placeholder="https://your-domain.com" value="${escapeHtml(cfg.publicBaseUrl || '')}"></label></div>`,
    note:()=>`Local: pilih Polling, jadi tidak butuh tunnel. Production webhook: ${location.origin}/webhooks/telegram/${authState?.user?.workspace?.id || 'WORKSPACE_ID'}/SECRET`
  },
  whatsapp: {
    title:'Connect WhatsApp Cloud API',
    fields: cfg => `
      <label>Meta Access Token<input name="accessToken" type="password" placeholder="EAAG..." ${cfg.accessTokenMasked ? '' : 'required'}><small>${cfg.accessTokenMasked ? `Saved: ${cfg.accessTokenMasked}` : 'System User / permanent token recommended for production'}</small></label>
      <div class="row"><label>Phone Number ID<input name="phoneNumberId" required value="${escapeHtml(cfg.phoneNumberId || '')}"></label><label>WABA ID<input name="wabaId" value="${escapeHtml(cfg.wabaId || '')}"></label></div>
      <div class="row"><label>Graph API Version<input name="graphVersion" value="${escapeHtml(cfg.graphVersion || 'v23.0')}"></label><label>Verify Token<input name="verifyToken" value="${escapeHtml(cfg.verifyToken || '')}" placeholder="make-a-random-token"></label></div>
      <label>Public Base URL<input name="publicBaseUrl" value="${escapeHtml(cfg.publicBaseUrl || '')}" placeholder="https://your-domain.com"></label>`,
    note:()=>`Webhook callback: ${location.origin}/webhooks/whatsapp/${authState?.user?.workspace?.id || 'WORKSPACE_ID'}. Untuk menerima chat dari Meta, backend harus memiliki HTTPS URL publik dan webhook dikonfigurasi di Meta App.`
  },
  instagram: {
    title:'Connect Instagram Messaging',
    fields: cfg => `
      <label>Meta Access Token<input name="accessToken" type="password" placeholder="EAAG..." ${cfg.accessTokenMasked ? '' : 'required'}><small>${cfg.accessTokenMasked ? `Saved: ${cfg.accessTokenMasked}` : 'Token must have the required Instagram messaging permissions'}</small></label>
      <div class="row"><label>Instagram Account ID<input name="igAccountId" required value="${escapeHtml(cfg.igAccountId || '')}"></label><label>Graph API Version<input name="graphVersion" value="${escapeHtml(cfg.graphVersion || 'v23.0')}"></label></div>
      <div class="row"><label>Verify Token<input name="verifyToken" value="${escapeHtml(cfg.verifyToken || '')}" placeholder="make-a-random-token"></label><label>Public Base URL<input name="publicBaseUrl" value="${escapeHtml(cfg.publicBaseUrl || '')}" placeholder="https://your-domain.com"></label></div>`,
    note:()=>`Webhook callback: ${location.origin}/webhooks/instagram/${authState?.user?.workspace?.id || 'WORKSPACE_ID'}. Akun Instagram profesional dan izin Meta yang sesuai diperlukan.`
  }
};

function openChannelDialog(type) {
  activeChannel = type;
  const schema = channelSchemas[type];
  const cfg = studioConfig?.channels?.[type] || {};
  channelDialogTitle.textContent = schema.title;
  channelFields.innerHTML = schema.fields(cfg);
  channelDialogNote.textContent = typeof schema.note === 'function' ? schema.note() : schema.note;
  disconnectChannelButton.hidden = !cfg.connected;
  connectChannelButton.textContent = cfg.connected ? 'Update & Verify' : 'Connect & Verify';
  setFormMessage(channelMessage, '');
  channelDialog.showModal();
}
document.querySelectorAll('[data-open-channel]').forEach(btn => btn.addEventListener('click', () => openChannelDialog(btn.dataset.openChannel)));
connectChannelButton?.addEventListener('click', async () => {
  if (!activeChannel) return;
  const payload = Object.fromEntries(new FormData(document.getElementById('channelForm')).entries());
  setFormMessage(channelMessage, 'Verifying credentials…');
  try {
    await apiRequest(`/api/channels/${activeChannel}/connect`, { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify(payload) });
    setFormMessage(channelMessage, `${activeChannel} connected.`, 'success');
    await loadStudio();
    setTimeout(() => channelDialog.close(), 550);
  } catch (err) { setFormMessage(channelMessage, err.message, 'error'); }
});
disconnectChannelButton?.addEventListener('click', async () => {
  if (!activeChannel) return;
  try {
    await apiRequest(`/api/channels/${activeChannel}/disconnect`, { method:'POST' });
    setFormMessage(channelMessage, `${activeChannel} disconnected.`, 'success'); await loadStudio(); setTimeout(() => channelDialog.close(), 450);
  } catch (err) { setFormMessage(channelMessage, err.message, 'error'); }
});

loadAuth();
